// Converte a resposta do Tally (ou dos scripts de teste) em campos simples
const body = $input.first().json.body || {};
const data = body.data || {};
const fields = data.fields || [];

function valor(chave) {
  const f = fields.find(x => (x.label || '').toLowerCase().includes(chave));
  if (!f || f.value == null) return '';
  // Perguntas de escolha do Tally chegam como lista de IDs + "options"
  if (Array.isArray(f.value)) {
    return f.value
      .map(v => ((f.options || []).find(o => o.id === v) || {}).text || v)
      .join(', ');
  }
  return String(f.value).trim();
}

const tally_id = data.responseId || data.submissionId || '';
return [{
  json: {
    tally_id,
    empresa_codigo: valor('empresa').toUpperCase(),   // campo oculto: link ?empresa=ACME
    nome: valor('nome'),
    email: valor('mail').toLowerCase(),
    telefone: valor('telefone'),
    tipo: valor('tipo'),
    impacto_cliente: valor('afetad'),
    urgencia_cliente: valor('urg'),
    descricao: valor('descr'),
    teste_carga: tally_id.startsWith('carga'),
    recebido_em: new Date().toISOString(),
  }
}];

// Empresas e KB ficam em cache por 15 min: economiza chamadas de API do Airtable
// (o plano free tem 1.000 chamadas por mês). O cache só persiste com o workflow ATIVO.
const sd = $getWorkflowStaticData('global');
const valido = !!sd.cacheEm && (Date.now() - sd.cacheEm) < 15 * 60 * 1000
  && Array.isArray(sd.empresas) && Array.isArray(sd.kb);
return [{ json: { cache_ok: valido } }];

// Guarda empresas e artigos lidos do Airtable no cache do workflow
const sd = $getWorkflowStaticData('global');
const pegar = r => ({ recId: r.json.id, ...(r.json.fields || r.json) });
// Códigos em maiúsculas e sem espaços: "Delta " no Airtable vira "DELTA", igual ao link ?empresa=DELTA
const cod = v => String(v || '').trim().toUpperCase();
sd.empresas = $('Buscar empresas').all().map(pegar).filter(e => e['Código'])
  .map(e => ({ ...e, 'Código': cod(e['Código']) }));
sd.kb = $('Buscar KB').all().map(pegar).filter(a => a.ID)
  .map(a => ({ ...a, Empresa: cod(a.Empresa) }));
sd.cacheEm = Date.now();
return [{ json: { cache_ok: true, empresas: sd.empresas.length, artigos: sd.kb.length } }];

// Escolhe a empresa, os artigos dela e os chamados abertos relacionados, e monta o prompt
const sd = $getWorkflowStaticData('global');
const t = $('Normalizar dados').first().json;
const empresa = (sd.empresas || []).find(e => e['Código'] === t.empresa_codigo && e.Ativa) || null;
const kb = (sd.kb || []).filter(a => a.Empresa === 'TODAS' || (empresa && a.Empresa === empresa['Código']));
// Candidatos a duplicado: mesmo solicitante (7 dias) ou incidente coletivo da mesma empresa (24 h)
const coletivo = x => !String(x || '').startsWith('Só');
const candidatos = (sd.recentes || []).filter(r => !r.auto && (
  (r.email === t.email && Date.now() - r.ts < 7 * 24 * 3600 * 1000) ||
  (r.empresa === t.empresa_codigo && coletivo(r.impacto) && coletivo(t.impacto_cliente)
    && Date.now() - r.ts < 24 * 3600 * 1000)
)).slice(-10);

const kbTexto = kb.map(a => `${a.ID} | ${a.Categoria} | ${a['Título']} | sintomas: ${a.Sintomas}`).join('\n') || 'nenhum';
const recentesTexto = candidatos.map(c => `${c.id} | ${c.email === t.email ? 'mesmo solicitante' : 'outra pessoa da empresa'} | ${c.impacto} | ${c.descricao}`).join('\n') || 'nenhum';
const candidatos_qtd = candidatos.length;

const prompt = `Você é analista de Service Desk N1 de um MSP que atende várias empresas.
Faça a triagem do chamado abaixo.

EMPRESA: ${empresa ? empresa.Nome + ' (' + empresa.Segmento + ')' : 'não identificada'}

CHAMADO
Tipo informado: ${t.tipo}
Pessoas afetadas: ${t.impacto_cliente}
Urgência informada: ${t.urgencia_cliente}
Descrição: ${t.descricao}

BASE DE CONHECIMENTO DESTA EMPRESA (ID | categoria | título | sintomas)
${kbTexto}

CHAMADOS ABERTOS RELACIONADOS (ID | quem abriu | pessoas afetadas | descrição)
${recentesTexto}

Responda SÓ com um JSON válido, sem nada antes ou depois, com estas chaves:
"categoria": uma de "Acesso e senha", "Hardware", "Impressora", "Rede e internet", "E-mail e Office", "Sistemas", "Segurança", "Outro"
"artigo_kb": ID do artigo que resolve o problema, ou null
"confianca": número de 0 a 1 sobre a categoria e o artigo
"duplicado_de": ID do chamado da lista acima que trata do MESMO problema (mesmo serviço, mesmo local ou mesmo sintoma; se for outra pessoa da empresa, é o mesmo incidente coletivo), ou null
"revisar_prioridade": true se a descrição mostrar risco diferente do que o cliente marcou (ex.: segurança, pedido de compra, empresa parada), senão false
"motivo": uma frase explicando a categoria e o risco
"resumo_n2": até 3 linhas para o técnico: problema, impacto, o que já se sabe
"resposta_cliente": rascunho curto e educado em português, usando os passos do artigo se houver

Não invente artigos nem IDs que não estão nas listas acima.`;

return [{ json: { prompt, candidatos_qtd } }];

// Lê a resposta da IA e aplica as regras de negócio da empresa (SLA, prioridade, resolução automática)
const sd = $getWorkflowStaticData('global');
const t = $('Normalizar dados').first().json;
const prompt = $('Montar contexto').first().json.prompt;
const empresa = (sd.empresas || []).find(e => e['Código'] === t.empresa_codigo && e.Ativa) || null;
const kb = (sd.kb || []).filter(a => a.Empresa === 'TODAS' || (empresa && a.Empresa === empresa['Código']));
// Candidatos a duplicado: mesmo solicitante (7 dias) ou incidente coletivo da mesma empresa (24 h)
const coletivo = x => !String(x || '').startsWith('Só');
const candidatos = (sd.recentes || []).filter(r => !r.auto && (
  (r.email === t.email && Date.now() - r.ts < 7 * 24 * 3600 * 1000) ||
  (r.empresa === t.empresa_codigo && coletivo(r.impacto) && coletivo(t.impacto_cliente)
    && Date.now() - r.ts < 24 * 3600 * 1000)
)).slice(-10);

const bruto = String($input.first().json.text || '');
let ia = {};
let ia_ok = false;
try {
  ia = JSON.parse(bruto.replace(/```json|```/g, '').trim());
  ia_ok = true;
} catch (e) { ia = {}; }

// Prioridade pela matriz ITIL (impacto x urgência): regra fixa, não a IA
const imp = t.impacto_cliente.startsWith('Setor') ? 3 : t.impacto_cliente.startsWith('Algumas') ? 2 : 1;
const urg = t.urgencia_cliente.startsWith('Alta') ? 3 : t.urgencia_cliente.startsWith('Média') ? 2 : 1;
const soma = imp + urg;
const prioridade = soma >= 6 ? 'P1' : soma === 5 ? 'P2' : soma === 4 ? 'P3' : 'P4';
// SLA vem do contrato da empresa; sem empresa, usa o mais rígido
const padrao = { P1: 15, P2: 60, P3: 240, P4: 720 };
const slaMin = empresa ? Number(empresa[`SLA ${prioridade} (min)`]) || padrao[prioridade] : padrao[prioridade];
const prazo = $now.setZone('America/Sao_Paulo').plus({ minutes: slaMin });

// Só aceita da IA o que existe de verdade
const CATS = ['Acesso e senha', 'Hardware', 'Impressora', 'Rede e internet', 'E-mail e Office', 'Sistemas', 'Segurança', 'Outro'];
const categoria = CATS.includes(ia.categoria) ? ia.categoria : 'Outro';
const artigo = kb.find(a => a.ID === ia.artigo_kb) || null;
const duplicado = candidatos.find(c => c.id === ia.duplicado_de) || null;
const confianca = typeof ia.confianca === 'number' ? ia.confianca : 0;

const revisao = !ia_ok || !empresa || prioridade === 'P1' || prioridade === 'P2' || !!duplicado
  || confianca < 0.7 || ia.revisar_prioridade === true || categoria === 'Segurança';

// Resolução automática: só P4, com artigo de autoatendimento, IA confiante e empresa que aceita
const resolve_sozinho = !revisao && prioridade === 'P4' && !!artigo && !!artigo.Autoatendimento
  && confianca >= 0.8 && !!(empresa && empresa['Resolução automática']);

const id = 'HD-' + (empresa ? empresa['Código'] : 'XXX') + '-'
  + $now.setZone('America/Sao_Paulo').toFormat('yyMMdd') + '-'
  + Math.random().toString(36).slice(2, 6).toUpperCase();
const prazoTexto = prazo.toFormat("dd/MM 'às' HH:mm");

let proximos;
if (resolve_sozinho) {
  proximos = `Este problema tem solução rápida. Siga estes passos: ${artigo['Solução']} Se não resolver, responda este e-mail com REABRIR e um técnico assume.`;
} else if (duplicado) {
  proximos = duplicado.email === t.email
    ? `Você já tem o chamado ${duplicado.id} aberto sobre o mesmo assunto. Vamos tratar os dois juntos.`
    : `Esse problema já foi informado por outra pessoa da sua empresa (chamado ${duplicado.id}). A equipe está tratando como um único incidente e você também será avisado quando resolver.`;
} else if (!revisao && artigo && artigo.Autoatendimento) {
  proximos = `Enquanto isso, tente estes passos: ${artigo['Solução']} Um técnico responde até ${prazoTexto}.`;
} else {
  proximos = `Um técnico vai analisar e responder até ${prazoTexto}.`;
}

const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const linha = (k, v) => `<tr><td style="padding:4px 12px 4px 0;color:#555">${k}</td><td style="padding:4px 0"><b>${esc(v)}</b></td></tr>`;
const email_html = `<p>Olá, ${esc(t.nome.split(' ')[0])}!</p>
<p>Recebemos seu chamado${empresa ? ' da ' + esc(empresa.Nome) : ''}. Confira se os dados estão certos:</p>
<table style="border-collapse:collapse;font-size:14px">
${linha('Número do chamado', id)}
${linha('Nome', t.nome)}
${linha('E-mail', t.email)}
${linha('Telefone', t.telefone)}
${linha('Categoria', categoria)}
${linha('Prioridade', prioridade + (resolve_sozinho ? '' : ' (1ª resposta até ' + prazoTexto + ')'))}
${linha('Descrição', t.descricao)}
</table>
<p><b>Próximos passos:</b> ${esc(proximos)}</p>
<p>Se algum dado estiver errado, responda este e-mail citando o número ${id}.</p>
<p>Service Desk</p>`;

return [{
  json: {
    ...t,
    id, prioridade, categoria,
    empresa_rec: empresa ? empresa.recId : null,
    empresa_nome: empresa ? empresa.Nome : 'Não identificada',
    revisao_humana: revisao,
    resolvido_auto: resolve_sozinho,
    status: resolve_sozinho ? 'Resolvido automaticamente' : revisao ? 'Aguardando revisão' : 'Aberto',
    prazo_iso: prazo.toISO(), prazo_texto: prazoTexto,
    artigo_kb: artigo ? artigo.ID : '',
    duplicado_de: duplicado ? duplicado.id : '',
    confianca,
    motivo_ia: ia.motivo || (ia_ok ? '' : 'IA não respondeu: triagem manual'),
    resumo_n2: ia.resumo_n2 || '',
    resposta_sugerida: ia.resposta_cliente || '',
    proximos_passos: proximos,
    email_html,
    enviar_email: !t.teste_carga,
    tokens_estimados: Math.round((prompt.length + bruto.length) / 4),
    tempo_triagem_s: Math.round(($now.toMillis() - new Date(t.recebido_em).getTime()) / 100) / 10,
  }
}];

// Guarda o chamado no cache para detectar duplicados sem gastar chamada de API
const sd = $getWorkflowStaticData('global');
const c = $('Preparar chamado').first().json;
const seteDias = 7 * 24 * 3600 * 1000;
sd.recentes = (sd.recentes || []).filter(r => Date.now() - r.ts < seteDias).slice(-500);
sd.recentes.push({ id: c.id, email: c.email, empresa: c.empresa_codigo, impacto: c.impacto_cliente,
  descricao: c.descricao, ts: Date.now(), auto: c.resolvido_auto });
return [{ json: c }];

